"""Value semantics for minisql.

SQL values are represented with Python objects: ``None`` for NULL, ``bool``
for booleans, ``int``/``float`` for numbers, and ``str`` for strings.
Booleans are deliberately *not* numbers, even though ``bool`` subclasses
``int`` in Python.

Every operation here raises :class:`minisql.errors.QueryError` when its
operands are invalid; no other exception type escapes.
"""

import functools
import math
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

from .errors import QueryError

__all__ = [
    "parse_field",
    "is_number",
    "type_name",
    "value_key",
    "same_value",
    "is_null",
    "truth",
    "not3",
    "and3",
    "or3",
    "compare",
    "in_list",
    "like",
    "negate",
    "arithmetic",
    "concat",
    "text",
    "scalar",
]

_INTEGER_RE = re.compile(r"-?[0-9]+")
_DECIMAL_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")

_COMPARISON_OPS = frozenset({"=", "!=", "<", "<=", ">", ">="})
_ARITHMETIC_OPS = frozenset({"+", "-", "*", "/"})

# Beyond this many decimal places a Python float cannot change any more, so
# ROUND can stop doing decimal work.  The limit is generous (well above the
# ~324 digits of a subnormal float) but small enough for ``Decimal``.
_ROUND_DIGIT_LIMIT = 400


# ---------------------------------------------------------------------------
# CSV fields and value inspection
# ---------------------------------------------------------------------------


def parse_field(text):
    """Convert one CSV field to ``None``, ``int``, ``float``, or ``str``."""
    if text == "":
        return None
    if _INTEGER_RE.fullmatch(text):
        try:
            return int(text)
        except ValueError:
            # Python 3.11+ refuses pathologically long integer strings.
            raise QueryError("integer field is too large") from None
    if _DECIMAL_RE.fullmatch(text):
        return float(text)
    return text


def is_number(value):
    """True only for int/float, never for bool."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def type_name(value):
    """Return SQL's name for a value's type."""
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "string"
    raise QueryError("unsupported value type: %s" % type(value).__name__)


def is_null(value):
    return value is None


def value_key(value):
    """A hashable key for grouping and DISTINCT.

    ``1`` and ``1.0`` share a key, booleans never share a key with numbers,
    and NULL has its own key.  NaN is canonicalised so that the key stays
    reflexive even though IEEE NaN comparison is not.
    """
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("boolean", value)
    if isinstance(value, int):
        return ("number", value)
    if isinstance(value, float):
        if math.isnan(value):
            return ("float-nan",)
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    raise QueryError("unsupported value type: %s" % type(value).__name__)


def same_value(a, b):
    """Equality for DISTINCT, without raising on mismatched types."""
    return value_key(a) == value_key(b)


# ---------------------------------------------------------------------------
# Three-valued logic
# ---------------------------------------------------------------------------


def truth(value):
    """Boolean value of a WHERE/HAVING condition; NULL counts as false."""
    if value is None:
        return False
    if isinstance(value, bool):
        return value
    raise QueryError(
        "expected a boolean value, found %s" % type_name(value)
    )


def _bool_operand(value, operator):
    if value is None or isinstance(value, bool):
        return value
    raise QueryError(
        "%s requires boolean operands, found %s"
        % (operator, type_name(value))
    )


def not3(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return not value
    raise QueryError(
        "NOT requires a boolean operand, found %s" % type_name(value)
    )


def and3(a, b):
    a = _bool_operand(a, "AND")
    b = _bool_operand(b, "AND")
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or3(a, b):
    a = _bool_operand(a, "OR")
    b = _bool_operand(b, "OR")
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


# ---------------------------------------------------------------------------
# Comparisons, IN, LIKE
# ---------------------------------------------------------------------------


def compare(op, a, b):
    """Compare two values, returning True/False or None for a NULL operand."""
    if op not in _COMPARISON_OPS:
        raise QueryError("unknown comparison operator: %s" % (op,))
    if a is None or b is None:
        return None

    if is_number(a) and is_number(b):
        pass
    elif isinstance(a, str) and isinstance(b, str):
        pass
    elif isinstance(a, bool) and isinstance(b, bool):
        pass
    else:
        raise QueryError(
            "cannot compare %s with %s" % (type_name(a), type_name(b))
        )

    # Use Python's operators directly so float NaN keeps its IEEE behaviour.
    if op == "=":
        return a == b
    if op == "!=":
        return a != b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    return a >= b


def in_list(value, items):
    """``value IN (items...)`` with SQL's NULL rules."""
    saw_null = value is None
    for item in items:
        if item is None:
            saw_null = True
            continue
        if value is None:
            continue
        if compare("=", value, item):
            return True
    return None if saw_null else False


@functools.lru_cache(maxsize=256)
def _like_regex(pattern):
    pieces = []
    for char in pattern:
        if char == "%":
            pieces.append(".*")
        elif char == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(char))
    # DOTALL makes ``_`` and ``%`` match newlines too; fullmatch anchors the
    # pattern to the whole string.
    return re.compile("".join(pieces), re.DOTALL)


def like(value, pattern):
    """Whole-string, case-sensitive SQL LIKE."""
    if value is None or pattern is None:
        return None
    if not isinstance(value, str) or not isinstance(pattern, str):
        raise QueryError(
            "LIKE requires string operands, found %s and %s"
            % (type_name(value), type_name(pattern))
        )
    return _like_regex(pattern).fullmatch(value) is not None


# ---------------------------------------------------------------------------
# Arithmetic and concatenation
# ---------------------------------------------------------------------------


def negate(value):
    if value is None:
        return None
    if is_number(value):
        return -value
    raise QueryError("cannot negate %s" % type_name(value))


def arithmetic(op, a, b):
    """Apply ``+``, ``-``, ``*``, or ``/`` (true division)."""
    if op not in _ARITHMETIC_OPS:
        raise QueryError("unknown arithmetic operator: %s" % (op,))
    if a is None or b is None:
        return None
    if not is_number(a) or not is_number(b):
        raise QueryError(
            "cannot apply %s to %s and %s"
            % (op, type_name(a), type_name(b))
        )

    if op == "/":
        if b == 0:
            return None
        try:
            return a / b
        except OverflowError:
            # A huge integer quotient that cannot be represented as a float.
            raise QueryError("numeric value out of range") from None

    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        return a * b
    except OverflowError:
        # Mixing a very large int with a float can overflow the conversion.
        raise QueryError("numeric value out of range") from None


def text(value):
    """The text form used by ``||``: booleans are lower-case, numbers str()."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float)):
        return str(value)
    if value is None:
        raise QueryError("NULL has no text form")
    raise QueryError("cannot convert %s to text" % type_name(value))


def concat(a, b):
    """``a || b``; NULL propagates, everything else is stringified."""
    if a is None or b is None:
        return None
    return text(a) + text(b)


# ---------------------------------------------------------------------------
# Scalar functions
# ---------------------------------------------------------------------------


def _to_float(value):
    try:
        return float(value)
    except (OverflowError, ValueError):
        raise QueryError("numeric value out of range") from None


def _round(value, digits=None):
    if not is_number(value):
        raise QueryError(
            "ROUND requires a numeric first argument, found %s"
            % type_name(value)
        )

    if digits is None:
        if isinstance(value, int):
            return value
        decimal_value = Decimal(str(value))
        if not decimal_value.is_finite():
            raise QueryError(
                "ROUND cannot round a non-finite value to an integer"
            )
        with localcontext() as context:
            context.prec = max(28, decimal_value.adjusted() + 10)
            rounded = decimal_value.quantize(
                Decimal(1), rounding=ROUND_HALF_UP
            )
        return int(rounded)

    if isinstance(digits, bool) or not isinstance(digits, int):
        raise QueryError(
            "ROUND requires an integer second argument, found %s"
            % type_name(digits)
        )

    if isinstance(value, int):
        decimal_value = Decimal(value)
        sign = -1.0 if value < 0 else 1.0
    else:
        if not math.isfinite(value):
            return float(value)
        decimal_value = Decimal(str(value))
        sign = math.copysign(1.0, value)

    if digits > _ROUND_DIGIT_LIMIT:
        return _to_float(value)
    if digits < -_ROUND_DIGIT_LIMIT:
        return -0.0 if sign < 0 else 0.0

    exponent = Decimal(1).scaleb(-digits)
    with localcontext() as context:
        # quantize's result may need far more digits than the default 28.
        context.prec = max(28, decimal_value.adjusted() + digits + 20)
        try:
            rounded = decimal_value.quantize(
                exponent, rounding=ROUND_HALF_UP
            )
        except InvalidOperation:
            raise QueryError("ROUND result is out of range") from None
    return _to_float(rounded)


def _argument_count_error(name, expected, actual):
    if expected == "1":
        raise QueryError(
            "%s expects 1 argument, got %d" % (name, actual)
        )
    raise QueryError(
        "%s expects %s arguments, got %d" % (name, expected, actual)
    )


def scalar(name, args):
    """Evaluate a scalar function on already-evaluated arguments."""
    name = name.upper()

    if name == "COALESCE":
        if not args:
            raise QueryError("COALESCE expects at least 1 argument, got 0")
        for arg in args:
            if arg is not None:
                return arg
        return None

    if name == "ROUND":
        if len(args) not in (1, 2):
            raise QueryError(
                "ROUND expects 1 or 2 arguments, got %d" % len(args)
            )
        if any(arg is None for arg in args):
            return None
        if len(args) == 1:
            return _round(args[0])
        return _round(args[0], args[1])

    arities = {"LOWER": 1, "UPPER": 1, "LENGTH": 1, "ABS": 1}
    if name not in arities:
        raise QueryError("unknown function: %s" % name)

    expected = arities[name]
    if len(args) != expected:
        _argument_count_error(name, str(expected), len(args))
    if any(arg is None for arg in args):
        return None

    value = args[0]

    if name in ("LOWER", "UPPER", "LENGTH"):
        if not isinstance(value, str):
            raise QueryError(
                "%s requires a string argument, found %s"
                % (name, type_name(value))
            )
        if name == "LOWER":
            return value.lower()
        if name == "UPPER":
            return value.upper()
        return len(value)

    if not is_number(value):
        raise QueryError(
            "ABS requires a numeric argument, found %s" % type_name(value)
        )
    return abs(value)

